package cn.mop.persistence;
import cn.mop.domain.DomainException;
import cn.mop.domain.inspection.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Consumer;
import static org.junit.jupiter.api.Assertions.*;
class InspectionSourceDocumentCodecTest {
    final ObjectMapper json=new ObjectMapper();final Instant time=Instant.parse("2026-10-04T00:00:00Z");
    UUID id(int n){return UUID.fromString("7b000000-0000-4000-8000-"+String.format("%012x",n));}
    InspectionSourceManifest manifest(){return manifest(List.of());}
    InspectionSourceManifest manifest(List<UUID> refs){var definition=new InspectionTemplate("router","合成",List.of(new InspectionTemplate.Item("a","bc","d",null),new InspectionTemplate.Item("empty","备注","未填项","")));var template=InspectionTemplate.Snapshot.capture(id(1),id(4),1,definition);var worksheet=new InspectionWorksheet(id(1),id(3),"合成设备",template,Map.of("a",new InspectionWorksheet.Observation(InspectionWorksheet.Result.ATTENTION,"😀\n\t原文",refs)));var content=new InspectionWorksheetContent(worksheet,null);return new InspectionSourceManifest(id(1),List.of(new InspectionSourceSnapshot(id(1),id(2),1,id(5),time,id(5),time,"CREATE",false,content)));}
    byte[] bytes(){return InspectionSourceDocumentCodec.encode(manifest());}
    InspectionSourceManifest decode(byte[] bytes){return InspectionSourceDocumentCodec.decode(bytes,id(1),InspectionSourceDocumentCodec.hash(bytes),manifest().fingerprint());}
    void bad(Consumer<ObjectNode> mutate)throws Exception{var root=(ObjectNode)json.readTree(bytes());mutate.accept(root);byte[] bytes=json.writeValueAsString(root).getBytes(StandardCharsets.UTF_8);assertEquals(503,assertThrows(DomainException.class,()->decode(bytes)).status);}
    ObjectNode source(ObjectNode root){return (ObjectNode)root.withArray("sources").get(0);}
    ObjectNode content(ObjectNode root){return (ObjectNode)source(root).get("content");}
    @Test void independentPythonUtf8DocumentGolden(){assertEquals(1185,bytes().length);assertEquals("cc920d7442bfb1a2f5801f5bb28ca1608e5126593b23b5a1bfd30a30cdf03b68",InspectionSourceDocumentCodec.hash(bytes()));}
    @Test void exactRoundTripRetainsUnknownTimeUnansweredNullEmptyAndUnverifiedFacts(){var actual=decode(bytes());assertEquals(manifest(),actual);assertNull(actual.sources().get(0).content().reportedPerformedAt());assertEquals(1,actual.sources().get(0).content().worksheet().summary().unanswered());assertFalse(actual.formalReportGeneratable());assertFalse(actual.reportPublished());assertNull(actual.periodTimeZone());assertArrayEquals(bytes(),InspectionSourceDocumentCodec.encode(actual));}
    @Test void encodingIsStableAndReturnedBytesAreDetached(){byte[] a=bytes(),b=bytes();assertArrayEquals(a,b);a[0]=0;assertArrayEquals(b,bytes());assertNotEquals(InspectionSourceDocumentCodec.hash(a),InspectionSourceDocumentCodec.hash(b));}
    @Test void unknownEvidenceReferencesRoundTripButGrantNoAccess(){var input=manifest(List.of(id(8),id(9)));var data=InspectionSourceDocumentCodec.encode(input);var actual=InspectionSourceDocumentCodec.decode(data,id(1),InspectionSourceDocumentCodec.hash(data),input.fingerprint());assertEquals(input,actual);assertFalse(actual.sources().get(0).evidenceAccessGranted());assertEquals(List.of(id(8),id(9)),actual.sources().get(0).content().worksheet().observations().get("a").evidenceIds());}
    @Test void emptyCollectionIsNotZeroTenantPopulation(){var input=new InspectionSourceManifest(id(1),List.of());byte[] data=InspectionSourceDocumentCodec.encode(input);var actual=InspectionSourceDocumentCodec.decode(data,id(1),InspectionSourceDocumentCodec.hash(data),input.fingerprint());assertEquals(0,actual.selectedSourceCount());assertNull(actual.tenantAssetPopulation());assertFalse(actual.formalReportGeneratable());}
    @Test void outerDigestAndIndependentlyScopedTenantAndManifestMustMatch(){byte[] b=bytes();for(String hash:Arrays.asList(null,"bad","f".repeat(64)))assertThrows(DomainException.class,()->InspectionSourceDocumentCodec.decode(b,id(1),hash,manifest().fingerprint()));assertThrows(DomainException.class,()->InspectionSourceDocumentCodec.decode(b,id(99),InspectionSourceDocumentCodec.hash(b),manifest().fingerprint()));assertThrows(DomainException.class,()->InspectionSourceDocumentCodec.decode(b,id(1),InspectionSourceDocumentCodec.hash(b),"f".repeat(64)));}
    @Test void rootShapeVersionAndTruthClaimOverridesAreRejected()throws Exception{bad(r->r.put("format","V2"));bad(r->r.put("published",true));bad(r->r.put("metric_version","invented"));bad(r->r.remove("manifest_sha256"));bad(r->r.put("tenant_id",id(99).toString()));}
    @Test void sourceIdentityRecordingAndLifecycleCannotBeChangedUnderSameHashes()throws Exception{bad(r->source(r).put("worksheet_id",id(99).toString()));bad(r->source(r).put("recorded_at",time.plusSeconds(1).toString()));bad(r->source(r).put("created_by",id(99).toString()));bad(r->source(r).put("version",2));bad(r->source(r).put("archived",true));bad(r->source(r).put("source_sha256","f".repeat(64)));}
    @Test void contentAndFullTemplateHashesAreRecomputedNotTrusted()throws Exception{bad(r->content(r).put("asset_name","changed"));bad(r->content(r).put("content_sha256","f".repeat(64)));bad(r->((ObjectNode)content(r).get("template")).put("name","changed"));bad(r->((ObjectNode)content(r).get("template")).put("content_sha256","f".repeat(64)));bad(r->((ObjectNode)content(r).path("template").path("items").get(0)).put("instruction","changed"));}
    @Test void nullEmptyMissingAndWrongAnswerTypesDoNotCollapse()throws Exception{bad(r->((ObjectNode)content(r).path("observations").get(0)).putNull("note"));bad(r->((ObjectNode)content(r).path("observations").get(0)).put("note",""));bad(r->((ObjectNode)content(r).path("observations").get(0)).remove("note"));bad(r->((ObjectNode)content(r).path("observations").get(0)).put("result","AUTO_NORMAL"));bad(r->content(r).put("reported_performed_at",time.toString()));}
    @Test void duplicateSourceOrObservationAndUnknownKeysAreRejected()throws Exception{bad(r->r.withArray("sources").add(source(r).deepCopy()));bad(r->content(r).withArray("observations").add(content(r).path("observations").get(0).deepCopy()));bad(r->((ObjectNode)content(r).path("observations").get(0)).put("key","foreign"));bad(r->content(r).put("evidence_access_granted",true));}
    @Test void duplicateJsonKeysTrailingBodiesWhitespaceAndMalformedUtf8FailClosed(){String raw=new String(bytes(),StandardCharsets.UTF_8);for(byte[] input:List.of((raw+"{}").getBytes(StandardCharsets.UTF_8),(" "+raw).getBytes(StandardCharsets.UTF_8),raw.replace("\"format\":","\"format\":\"ignored\",\"format\":").getBytes(StandardCharsets.UTF_8),new byte[]{(byte)0xc3,0x28}))assertThrows(DomainException.class,()->decode(input));}
    @Test void zeroMissingAndOversizeDocumentsRejectBeforeParsing(){assertThrows(DomainException.class,()->InspectionSourceDocumentCodec.decode(null,id(1),"0".repeat(64),"0".repeat(64)));assertThrows(DomainException.class,()->decode(new byte[0]));assertThrows(DomainException.class,()->InspectionSourceDocumentCodec.decode(new byte[InspectionSourceDocumentCodec.MAX_DOCUMENT_BYTES+1],id(1),"0".repeat(64),"0".repeat(64)));}
    @Test void canonicalTimestampsAndSafeVersionTypesAreRequired()throws Exception{bad(r->source(r).put("created_at","2026-10-04T00:00:00.000Z"));bad(r->source(r).put("recorded_at","2026-10-04T08:00:00+08:00"));bad(r->source(r).put("version","1"));bad(r->source(r).put("version",1.0));bad(r->source(r).put("version",9_007_199_254_740_991L));}
    @Test void declaredSourceLimitIsEnforcedBeforeConstructingSnapshots()throws Exception{bad(r->{var s=source(r).deepCopy();var values=r.putArray("sources");for(int n=0;n<1001;n++)values.add(s.deepCopy());});}
    @Test void deeplyNestedAndOverlongTokensAreBounded(){for(String raw:List.of("[".repeat(11)+"0"+"]".repeat(11),"\""+"x".repeat(12001)+"\""))assertThrows(DomainException.class,()->decode(raw.getBytes(StandardCharsets.UTF_8)));}
    @Test void newRevisionDocumentCannotMutatePreviouslyEncodedHistory(){var original=manifest();byte[] before=InspectionSourceDocumentCodec.encode(original);var s=original.sources().get(0);var changed=new InspectionSourceSnapshot(s.tenantId(),s.worksheetId(),2,s.createdBy(),s.createdAt(),s.recordedBy(),s.recordedAt().plusMillis(1),"ARCHIVE",true,s.content());var next=new InspectionSourceManifest(id(1),List.of(s,changed));InspectionSourceDocumentCodec.encode(next);assertEquals(original,decode(before));assertNotEquals(original.fingerprint(),next.fingerprint());}
    @Test void maximumSourceAndChecklistCountsStillRoundTripWithinDeclaredTokenBudget(){
        var items=new ArrayList<InspectionTemplate.Item>();var answers=new LinkedHashMap<String,InspectionWorksheet.Observation>();for(int n=0;n<100;n++){String key="a"+n;items.add(new InspectionTemplate.Item(key,"s","l",null));answers.put(key,new InspectionWorksheet.Observation(InspectionWorksheet.Result.NORMAL,"n",List.of()));}
        var template=InspectionTemplate.Snapshot.capture(id(1),id(4),1,new InspectionTemplate("router","token_bound",items));var content=new InspectionWorksheetContent(new InspectionWorksheet(id(1),id(3),"asset",template,answers),null);var sources=new ArrayList<InspectionSourceSnapshot>();for(int n=0;n<1000;n++)sources.add(new InspectionSourceSnapshot(id(1),id(100+n),1,id(5),time,id(5),time,"CREATE",false,content));var input=new InspectionSourceManifest(id(1),sources);byte[] data=InspectionSourceDocumentCodec.encode(input);assertTrue(data.length<=InspectionSourceDocumentCodec.MAX_DOCUMENT_BYTES);var decoded=InspectionSourceDocumentCodec.decode(data,id(1),InspectionSourceDocumentCodec.hash(data),input.fingerprint());assertEquals(1000,decoded.selectedSourceCount());assertEquals(input,decoded);
    }
    @Test void reorderedSourceArrayIsNotSilentlyNormalizedAsAnAcceptedStoredDocument()throws Exception{
        var first=manifest().sources().get(0);var other=new InspectionSourceSnapshot(id(1),id(9),1,id(5),time,id(5),time,"CREATE",false,first.content());var input=new InspectionSourceManifest(id(1),List.of(first,other));byte[] data=InspectionSourceDocumentCodec.encode(input);var document=(ObjectNode)json.readTree(data);var array=document.withArray("sources");var a=array.get(0);array.set(0,array.get(1));array.set(1,a);byte[] changed=json.writeValueAsString(document).getBytes(StandardCharsets.UTF_8);assertThrows(DomainException.class,()->InspectionSourceDocumentCodec.decode(changed,id(1),InspectionSourceDocumentCodec.hash(changed),input.fingerprint()));
    }

}
